export default function MobileFooterSticky({
  tourDetail,
  total,
  availabilityLoading,
  paxRoomMatch,
}: {
  tourDetail: any;
  total: any;
  availabilityLoading: any;
  paxRoomMatch: any;
}) {
  return (
    <div className="tw-fixed tw-bottom-0 tw-inset-x-0 tw-z-30 tw-bg-white tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0] tw-p-2 lg:tw-hidden">
      <div className="tw-flex tw-items-center">
        <div className="tw-w-3/4 tw-pr-2">
          <span className="tw-font-semibold tw-text-[#14101c]">
            {tourDetail.name}
          </span>
        </div>
        <div className="tw-w-1/4 tw-text-center tw-border-0 tw-border-l tw-border-solid tw-border-[#ebe7f0]">
          <strong className="tw-text-[#14101c]">Total</strong>
          {availabilityLoading || !paxRoomMatch ? (
            <div className="tw-mt-1 tw-mx-auto tw-h-4 tw-w-3/4 tw-animate-pulse tw-rounded tw-bg-[#ece9f1]"></div>
          ) : (
            <p className="tw-m-0 tw-text-[#14101c]">{total}</p>
          )}
        </div>
      </div>
    </div>
  );
}
