import { apiClient } from "@/lib/apiClient";

export function sendMail({ requestParameters }: { requestParameters: any }) {
  const res = fetch(
    "https://tour-categories.travelshopbooking.com/jobs/error-notification.php",
    {
      method: "POST",
      body: JSON.stringify(requestParameters),
      cache: "no-store",
    }
  ).then((res) => res.json());

  return res;
}

export function sendMailCheckout({
  requestParameters,
}: {
  requestParameters: any;
}) {
  // Sadece production'da bildirim gönder: local/development ortamda checkout
  // formuna girilen test verileri satış ekibine e-posta olarak düşmesin.
  // SERVER, next.config.js `env` ile client paketine gömülür.
  if (process.env.SERVER !== "production") {
    return Promise.resolve(null);
  }

  // apiv3 B2C: POST /bookings/abandoned-cart (terk edilen sepet ekip bildirimi).
  return apiClient("/bookings/abandoned-cart", {
    method: "POST",
    body: requestParameters,
  });
}
