"use client";

import { useState } from "react";

/**
 * Checkout'ta promosyon kodu ALANI yok — kod bir sonraki adımda, rezervasyon
 * oluştuktan sonra ödeme ekranında giriliyor (indirim gerçek rezervasyon tutarına
 * uygulanabilsin diye).
 *
 * Ama toplam tutarın olduğu yerde müşteri kodu burada arıyor; bulamayınca kodun
 * geçersiz olduğunu sanıp vazgeçebiliyor. Bu ipucu tam da o soruyu sorduğu yerde
 * cevaplıyor. Bilerek pasif: kutu açmıyor, istek atmıyor.
 */
export default function PromoCodeHint() {
  const [open, setOpen] = useState(false);

  return (
    <div className="tw-mt-3">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="tw-flex tw-items-center tw-gap-1.5 tw-border-0 tw-bg-transparent tw-p-0 tw-text-[13px] tw-font-semibold tw-text-[#854ec9] tw-cursor-pointer"
      >
        Have a promo code?
        <svg
          width="12"
          height="12"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="3"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
          className={`tw-transition-transform ${open ? "tw-rotate-180" : ""}`}
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
      </button>

      {open && (
        <div className="tw-mt-2 tw-flex tw-items-start tw-gap-2 tw-rounded-[10px] tw-bg-[#f5f0fc] tw-px-3 tw-py-2.5">
          <span className="tw-text-[14px] tw-leading-none">🏷️</span>
          <p className="tw-m-0 tw-text-[12.5px] tw-leading-relaxed tw-text-[#5d556c]">
            You&apos;ll be able to enter your code on the{" "}
            <strong className="tw-font-semibold tw-text-[#3f3a4d]">
              next step
            </strong>
            , right before you pay — your discount will be applied to this total.
          </p>
        </div>
      )}
    </div>
  );
}
