import { hasCookie, getCookie } from "cookies-next";
import { apiClient, ApiError } from "@/lib/apiClient";
import { getAttributionToken } from "@/lib/affiliateTracking";

// apiv3 B2C: POST /bookings/new-booking (tur checkout). Login'liyse sanctum, değilse app-token.
// Çağıran bileşen 422'de doğrudan errors nesnesini, diğer hatalarda {general:[...]} bekliyor →
// ApiError'ı bu sözleşmeye çeviriyoruz.
export default async function postBooking({
  requestParameters,
}: {
  requestParameters: any;
}) {
  const token = hasCookie("auth-token-v3")
    ? (getCookie("auth-token-v3") as string)
    : undefined;

  // Affiliate atfı: cookie'deki tıklama token'ı. apiv3 bunu doğrular ve geçersizse
  // sessizce yok sayar — rezervasyonu asla etkilemez.
  const attributionToken = getAttributionToken();

  try {
    return await apiClient("/bookings/new-booking", {
      method: "POST",
      auth: token ? "sanctum" : "app-token",
      token,
      body: attributionToken
        ? { ...requestParameters, attribution_token: attributionToken }
        : requestParameters,
    });
  } catch (e) {
    if (e instanceof ApiError && e.status === 422) {
      throw e.errors ?? {};
    }
    throw {
      general: [
        "An error occurred while processing your booking. Please try again later.",
      ],
    };
  }
}
